CASE Step_State OF
  0: (* Idle *)
    Fill_Valve := FALSE; Mixer_Motor := FALSE; Drain_Valve := FALSE;
    IF Start_PB AND NOT Fault_State AND Emergency_Stop AND NOT Abort_PB THEN
        Step_State := 1;
        Batch_Complete := FALSE;
    END_IF;
  1: (* Fill *)
    Fill_Valve := TRUE;
    IF High_Level THEN Step_State := 2; END_IF;
  2: (* Mix *)
    Mixer_Motor := TRUE;
    IF Mix_Timer_Done THEN Step_State := 3; END_IF;
  3: (* Drain *)
    Drain_Valve := TRUE;
    IF Low_Level THEN
        Step_State := 0;
        Batch_Complete := TRUE;
    END_IF;
  ELSE:
    Fill_Valve := FALSE; Mixer_Motor := FALSE;
    Drain_Valve := FALSE; Step_State := 0;
END_CASE;
